script.setup:
const s=ctx.state,gl=ctx.gl;s.canvas=new OffscreenCanvas(1,1);s.c=s.canvas.getContext('2d');s.texture=gl.createTexture();s.bitmaps=[];
s.image=async name=>{const b=await createImageBitmap(await(await fetch(ctx.assets[name])).blob());s.bitmaps.push(b);return b;};
s.json=async name=>await(await fetch(ctx.assets[name])).json();
s.show=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,`#version 300 es
precision highp float;in vec2 v_uv;out vec4 outColor;uniform sampler2D u_image;void main(){outColor=texture(u_image,vec2(v_uv.x,1.-v_uv.y));}`);
s.meta=await s.json('result.json');s.a=await s.image('input.png');s.spectrum=await s.image('spectrum.png');s.want=false;

script.render:
const s=ctx.state,gl=ctx.gl,u=ctx.uniforms,[w,h]=ctx.resolution,c=s.c,m=Math.min(w,h);
if(s.canvas.width!==w||s.canvas.height!==h){s.canvas.width=w;s.canvas.height=h;}c.fillStyle='#09131f';c.fillRect(0,0,w,h);
const size=m*.8,left=(w-size)/2,top=(h-size)/2;
const caption=(text)=>{c.fillStyle='#bccbd8';c.font=Math.max(12,m*.021)+'px sans-serif';c.textAlign='center';c.fillText(text,w/2,h/2+m*.46);};
c.drawImage(s.a,w/2-size*.45,h/2-size*.51,size*.9,size*.675);c.drawImage(s.spectrum,w/2-size*.5,h/2+size*.22,size,size*.36);if(u.u_listen!==s.want){s.want=u.u_listen;if(s.want){if(s.audio){s.audio.currentTime=0;s.audio.play().catch(e=>{s.error=String(e);});}else ctx.utils.audio.play('signal.wav',{volume:.06}).then(a=>{s.audio=a;if(s.dead||!s.want)a.pause();}).catch(e=>{s.error=String(e);});}else s.audio?.pause();}if(s.audio&&!s.audio.paused){const x=w/2-size*.5+size*s.audio.currentTime/s.meta.duration;c.strokeStyle='#ffbc78';c.beginPath();c.moveTo(x,h/2+size*.22);c.lineTo(x,h/2+size*.58);c.stroke();}caption(s.error||'Robot8BW · '+s.meta.duration.toFixed(2)+' s · 11025 Hz');gl.bindTexture(gl.TEXTURE_2D,s.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,s.canvas);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.useProgram(s.show);ctx.utils.bindTexture(s.show,'u_image',s.texture,0);ctx.utils.drawFullscreen(s.show);
ctx.publish('audio',s.error||(s.audio&&!s.audio.paused?'Playing '+s.audio.currentTime.toFixed(2)+' s':'Ready'));
